(()=>{
 const el=(tag,value='')=>{const e=document.createElement(tag);e.textContent=value;return e;};
 const api=async(path,body)=>{const r=await fetch('/api/admin/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error);return d;};
 const labels={scheduled:'Запланировано',retry:'Ошибка — ожидает повтора',sending:'Передаётся провайдеру',accepted:'Отправлено провайдеру',delivered:'Доставлено',unknown:'Отправка не подтверждена — нужна сверка',failed:'Ошибка',cancelled:'Отменено'};
 const date=n=>n?new Date(n).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'}):'—';
 const status=j=>j.status==='cancelled'?({rescheduled:'Отменено из-за переноса',cancelled:'Отменено из-за отмены брони',completed:'Не отправлено: прокат начался или завершён',expired:'Не отправлено: время брони прошло'}[j.cancel_reason]||'Отменено'):labels[j.status]||j.status;
 function job(j){const p=el('p',`${status(j)}. План: ${date(j.due)}. Отправка: ${date(j.sent_at)}. Попыток: ${j.attempts}. ${j.last_error||''}`);if(j.cancel_reason&&j.status!=='cancelled')p.append(el('small',' Бронь после начала отправки изменена/отменена; уже переданное сообщение отозвать нельзя.'));return p;}
 window.smsInquiry=(card,r)=>{
  const box=el('details'),summary=el('summary','SMS за 1 час');box.append(summary);let loaded=false;
  box.ontoggle=async()=>{if(!box.open||loaded)return;loaded=true;try{const d=await api('sms?inquiry='+r.id);if(!d.jobs.length)box.append(el('p','Не запланировано: заявка не подтверждена, нет времени посещения или телефон не поддерживается.'));d.jobs.forEach(j=>box.append(job(j)));}catch(e){box.append(el('p',e.message));}};card.append(box);
  if(['new','confirmed'].includes(r.status)&&r.details.plan!=='season'){
   const details=el('details');details.append(el('summary','Перенести дату / время'));const f=el('form'),input=el('input');input.type='datetime-local';input.required=true;input.value=r.details.date+'T'+r.details.time;input.step='1800';const label=el('label','Новое время · Москва');label.append(input);const button=el('button','Сохранить перенос'),notice=el('p');f.append(label);const ret=el('input');if(r.details.plan==='takeaway'){ret.type='date';ret.required=true;ret.value=r.details.returnDate;const rl=el('label','Дата возврата');rl.append(ret);f.append(rl);}f.append(button,notice);f.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{const [date,time]=input.value.split('T');await api('inquiry-reschedule',{id:r.id,revision:r.revision,date,time,...(ret.value?{returnDate:ret.value}:{})});window.calendarLoad?.();document.querySelector('#inquiry-refresh').click();}catch(e){notice.textContent=e.message;}finally{button.disabled=false;}};details.append(f);card.append(details);
  }
 };
 let loaded=false;
 window.smsLoad=async user=>{
  if(loaded)return;loaded=true;const root=el('section');root.className='panel';root.id='sms-settings';root.append(el('h2','СМС и уведомления'));document.querySelector('#workspace').append(root);const notice=el('p');notice.setAttribute('role','status');root.append(notice);
  try{
   const d=await api('sms');if(user.role==='admin'){
    let settings=d.settings;const f=el('form');const fields={};
    for(const [name,label,type] of [['enabled','Включить платную отправку СМС','checkbox'],['promoEnabled','СМС с промокодом','checkbox'],['remindersEnabled','Напоминания за 1 час','checkbox'],['dailyLimit','Лимит сообщений в день (не рублей и не SMS-сегментов)','number'],['sign','Имя отправителя SMS Aero','text'],['YANDEX_NAVIGATOR_URL','Общая ссылка на Яндекс.Навигатор','url'],['BOOKING_LATE_CANCEL_MINUTES','Отмена при опоздании более, минут','number'],['promoCode','Промокод','text'],['promoAmount','Скидка, ₽','number']]){const l=el('label',label),i=el('input');i.type=type;i.name=name;if(type==='checkbox')i.checked=settings[name];else{i.value=settings[name];i.required=true;}l.append(i);f.append(l);fields[name]=i;}
    root.append(el('p','Телефон станции: '+settings.STATION_PHONE+'. Изменяется в «Содержимое сайта и SEO» после публикации. Ссылка общая для промокода и напоминаний. Все времена — московские.'));
    root.append(el('p','СМС оплачиваются с баланса SMS Aero. Длинное сообщение состоит из нескольких платных частей; у некоторых операторов пакетная тарификация. Отправка может задержаться на модерации. Неоднозначный результат не повторяется автоматически.'));
    const button=el('button','Сохранить настройки СМС');f.append(button);f.onsubmit=async e=>{e.preventDefault();button.disabled=true;try{const b={revision:settings.revision};for(const [k,i] of Object.entries(fields))b[k]=i.type==='checkbox'?i.checked:i.type==='number'?Number(i.value):i.value;settings=(await api('sms-settings',b)).settings;notice.textContent='Настройки сохранены. '+(settings.enabled?(settings.transportEnabled?'Отправка включена.':'Отправка заблокирована на сервере; настройка сохранена.'):'Отправка выключена.');}catch(e){notice.textContent=e.message;}finally{button.disabled=false;}};root.append(f);
   }
   const journal=el('details');journal.append(el('summary','Журнал СМС (последние 100)'));const refresh=el('button','Обновить журнал'),list=el('div');refresh.onclick=async()=>{try{const d=await api('sms');list.replaceChildren(...d.jobs.map(j=>{const a=el('article');a.append(el('b',`№ ${j.id} · ${j.kind==='promo'?'Промокод':'Бронь № '+j.inquiry_id}`),job(j));return a;}));}catch(e){notice.textContent=e.message;}};journal.append(refresh,list);root.append(journal);
   const clients=el('details');clients.open=true;clients.append(el('summary','Единая база клиентов'));const search=el('form'),q=el('input');q.placeholder='Имя или телефон';q.setAttribute('aria-label','Поиск клиента');search.append(q,el('button','Найти'));const rows=el('div');search.onsubmit=async e=>{e.preventDefault();try{const d=await api('clients?q='+encodeURIComponent(q.value));rows.replaceChildren();for(const c of d.clients){const a=el('article');a.className='rental';a.append(el('h3',c.name),el('p','+'+c.phone),el('p','Первое обращение: '+date(c.first_seen)),el('p','Согласие на рекламу: '+(c.marketing_consent?'да':'нет')));for(const b of c.bookings){const details=JSON.parse(b.details);a.append(el('p',`Бронь № ${b.id}: ${details.date||'сезон'} ${details.time||''}, ${b.status}`));}for(const discount of c.discounts){a.append(el('p',`${discount.code}: ${discount.amount} ₽ · ${discount.redeemed?'Использован '+date(discount.redeemed):'Не использован'}`));if(!discount.redeemed){const use=el('button','Отметить использование скидки');use.onclick=async()=>{use.disabled=true;try{await api('promo-redeem',{id:discount.id});use.textContent='Использование отмечено';}catch(e){notice.textContent=e.message;use.disabled=false;}};a.append(use);}}rows.append(a);}if(!d.clients.length)rows.append(el('p','Клиенты не найдены.'));}catch(e){notice.textContent=e.message;}};clients.append(search,rows);(document.querySelector('#clients-slot')||root).append(clients);if(location.hash==="#sms-settings")root.scrollIntoView();
  }catch(e){notice.textContent=e.message;loaded=false;}
 };
})();
